-- Notifications/vetoes only; every handler is scoped to Threshold records.
UPDATE CustomModOptions SET Value=1 WHERE Name IN ('EVENTS_CAN_MOVE_INTO','EVENTS_UNIT_CONVERTS','EVENTS_UNIT_UPGRADES');
CREATE TEMP TABLE THCClone AS SELECT * FROM "Civilizations" WHERE Type='CIVILIZATION_AMERICA';
UPDATE THCClone SET "ID"=NULL,"Type"='CIVILIZATION_THRESHOLD_COURT',"Description"='TXT_KEY_THC_CIV',"ShortDescription"='TXT_KEY_THC_SHORT',"Adjective"='TXT_KEY_THC_ADJECTIVE',"Civilopedia"='TXT_KEY_THC_CIV_PEDIA',"CivilopediaTag"='TXT_KEY_THC_CIV5',"Strategy"='TXT_KEY_THC_STRATEGY',"DefaultPlayerColor"='PLAYERCOLOR_THRESHOLD',"Playable"=1,"AIPlayable"=0,"PackageID"=NULL,"DawnOfManQuote"='TXT_KEY_THC_DAWN',"DawnOfManAudio"='',"DawnOfManImage"='THC_Dawn.dds',"MapImage"='THC_Map.dds',"PortraitIndex"=0,"IconAtlas"='THC_CIV_ATLAS',"AlphaIconAtlas"='THC_ALPHA_ATLAS';
DROP TABLE THCClone;
CREATE TEMP TABLE THCClone AS SELECT * FROM "Leaders" WHERE Type='LEADER_WASHINGTON';
UPDATE THCClone SET "ID"=NULL,"Type"='LEADER_QUEEN_ELSEWHERE',"Description"='TXT_KEY_THC_LEADER',"Civilopedia"='TXT_KEY_THC_LEADER_PEDIA',"CivilopediaTag"='TXT_KEY_THC_QUEEN',"PackageID"=NULL,"PortraitIndex"=0,"IconAtlas"='THC_LEADER_ATLAS',"ArtDefineTag"='THC_LeaderScene.xml';
DROP TABLE THCClone;
CREATE TEMP TABLE THCClone AS SELECT * FROM "Units" WHERE Type='UNIT_PIKEMAN';
UPDATE THCClone SET "ID"=NULL,"Type"='UNIT_THRESHOLD_HINGEGUARD',"Description"='TXT_KEY_THC_UNIT',"Civilopedia"='TXT_KEY_THC_UNIT_PEDIA',"Help"='TXT_KEY_THC_UNIT_HELP',"Strategy"='TXT_KEY_THC_UNIT_STRATEGY',"IconAtlas"='THC_OBJECT_ATLAS',"PortraitIndex"=1;
DROP TABLE THCClone;
UPDATE Units SET Moves=Moves+1 WHERE Type='UNIT_THRESHOLD_HINGEGUARD';
CREATE TEMP TABLE THCClone AS SELECT * FROM "Buildings" WHERE Type='BUILDING_MARKET';
UPDATE THCClone SET "ID"=NULL,"Type"='BUILDING_THRESHOLD_HOUSE',"Description"='TXT_KEY_THC_BUILDING',"Civilopedia"='TXT_KEY_THC_BUILDING_PEDIA',"Help"='TXT_KEY_THC_BUILDING_HELP',"Strategy"='TXT_KEY_THC_BUILDING_STRATEGY',"IconAtlas"='THC_OBJECT_ATLAS',"PortraitIndex"=0;
DROP TABLE THCClone;
